const ozGeography1Zor = <(String, String, List<String>, String)>[
  ('Aşağıdaki özelliklerden hangisi Türkiye\'nin matematik konumuyla değil özel konumuyla açıklanır?', 'Karadeniz kıyılarında her mevsim yağış görülmesi', ['Güneşin hiçbir zaman tam tepeye gelmemesi', 'Kuzeyde gece-gündüz farkının güneye göre büyük olması', 'Doğu ile batı arasında 76 dakika yerel saat farkı olması'], 'Karadeniz kıyısında her mevsim yağış görülmesi dağların uzanışı ve denizden gelen nemli hava kütleleriyle, yani özel konumla ilgilidir; diğerleri enlem ve boylamın sonucudur.'),
  ('21 Haziran\'da Sinop ile Anamur karşılaştırıldığında Sinop için aşağıdakilerden hangisi doğrudur?', 'Gündüz süresi daha uzundur.', ['Öğle güneşi daha yüksektedir.', 'Güneş Anamur\'dan daha geç doğar.', 'Gölge boyu öğlende daha kısadır.'], 'Yaz gündönümünde kuzeye gidildikçe gündüz uzar; ancak güneş açısı küçüldüğünden gölge uzar ve öğle güneşi alçalır.'),
  ('Ege Denizi\'nin yerinde bulunan Egeid karasının çökmesi ve Ege Denizi\'nin oluşması hangi zamanın olayıdır?', 'Tersiyer sonu ile Kuaterner', ['Paleozoik başı', 'Mesozoik ortası', 'Prekambriyen sonu'], 'Egeid karası Tersiyer\'in sonlarından itibaren kırılıp çökmüş, Ege Denizi bu çökme alanında oluşmuştur.'),
  ('Toros Dağları\'nda karstik şekillerin yaygın olmasının jeolojik kökeni nedir?', 'Mesozoik\'te Tetis\'te biriken kalın kalker tabakaları', ['Paleozoik\'te oluşan granit kütleleri', 'Kuaterner\'deki volkanik lav örtüleri', 'Tersiyer\'de oluşan linyit katmanları'], 'Kalker, karbonik asitli suyla çözündüğünden Toroslar\'daki kalın kalker katmanları mağara, dolin ve polye gibi karstik şekillerin oluşmasına zemin hazırlamıştır.'),
  ('Kuzey Anadolu Fay Hattı\'nın doğu ucunda Doğu Anadolu Fay Hattı ile birleştiği yer neresidir?', 'Karlıova', ['Erzincan Ovası', 'Muş Ovası', 'Malatya Ovası'], 'Kuzey Anadolu ve Doğu Anadolu fayları Bingöl\'ün Karlıova ilçesi çevresinde birleşir.'),
  ('Türkiye\'nin ortalama yükseltisinin fazla olmasında aşağıdakilerden hangisinin payı en büyüktür?', 'Anadolu\'nun Tersiyer sonunda epirojenik olarak yükselmesi', ['Kuaterner\'deki deniz ilerlemesi', 'Paleozoik masiflerin aşınması', 'Karstik çözünmenin yaygın olması'], 'Anadolu, Tersiyer sonundan itibaren toptan yükselmiş; bu da ortalama yükseltinin 1.000 metreyi aşmasına yol açmıştır.'),
  ('Karaman ile Mut (Mersin) arasında Toroslar\'ı aşan geçit hangisidir?', 'Sertavul Geçidi', ['Gülek Boğazı', 'Çubuk Beli', 'Zigana Geçidi'], 'Sertavul Geçidi Orta Toroslar\'da Karaman\'ı Göksu vadisine ve Silifke\'ye bağlar.'),
  ('Niğde ile Mersin arasında uzanan, Orta Toroslar\'ın yüksek kütlelerinden biri olan ve zirvesi Medetsiz olan dağ hangisidir?', 'Bolkar Dağları', ['Aladağlar', 'Geyik Dağları', 'Dedegöl Dağları'], 'Bolkar Dağları Niğde-Mersin arasında yer alır; en yüksek tepesi Medetsiz\'dir.'),
  ('Aşağıdaki dağ çiftlerinden hangisinde her ikisi de volkanik kökenlidir?', 'Hasan - Tendürek', ['Uludağ - Erciyes', 'Kaçkar - Ağrı', 'Bolkar - Süphan'], 'Hasan Dağı İç Anadolu\'da, Tendürek Doğu Anadolu\'da bulunan volkanlardır. Uludağ granit kütle, Kaçkar ve Bolkar kıvrım dağlarıdır.'),
  ('Doğu Anadolu\'daki volkanik dağların yoğunlaşmasının tektonik nedeni nedir?', 'Arap ve Avrasya levhalarının sıkıştırmasıyla oluşan kırıklardan magmanın yükselmesi', ['Bölgenin eski bir Paleozoik masif olması', 'Karstik çözünmenin magmayı yüzeye çıkarması', 'Bölgenin Kuaterner\'de denizle kaplanması'], 'Levha çarpışmasının yarattığı kırıklar magmanın yüzeye ulaşmasını kolaylaştırmıştır; Ağrı, Süphan, Tendürek ve Nemrut bu sürecin ürünüdür.'),
  ('Konya Ovası\'nın oluşumunu en iyi açıklayan ifade hangisidir?', 'Kapalı havzadaki eski bir göl tabanının kuruması', ['Bir akarsuyun denize döküldüğü yerde delta oluşturması', 'Lav akıntısının vadiyi doldurması', 'Kalkerin çözünmesiyle oluşan dar bir dolin'], 'Konya Ovası Kuaterner\'de büyük bir göl ile kaplıydı; göl çekildikçe düz taban ortaya çıkmıştır.'),
  ('Çatalca-Kocaeli Platosu oluşum bakımından nasıl bir yer şeklidir?', 'Aşınım düzlüğü', ['Lav platosu', 'Karstik plato', 'Tektonik çanak'], 'Bu düzlük eski bir dağlık alanın uzun süre aşınarak alçalmasıyla oluşmuş; daha sonra hafifçe yükselmiş bir peneplendir.'),
  ('Mersin\'de yer alan, kalker yapısı nedeniyle yüzey suyunun az, karstik şekillerin ise yaygın olduğu plato hangisidir?', 'Taşeli Platosu', ['Uzunyayla Platosu', 'Bozok Platosu', 'Haymana Platosu'], 'Orta Toroslar\'daki Taşeli Platosu geçirimli kalkerlerden oluşur; suyun yer altına sızması yüzeyi kuraklaştırır.'),
  ('Karstik bir arazide yüzey akışının az, kaynakların ise dağ eteklerinde güçlü olmasının nedeni nedir?', 'Suyun kalker çatlaklarından yer altına sızıp eteklerde çıkması', ['Yağışın bu alanlarda hiç görülmemesi', 'Toprağın killi ve geçirimsiz olması', 'Akarsuların buzullarla beslenmesi'], 'Kalker geçirimli olduğundan yağış suyu derine iner, yer altı kanallarında ilerler ve geçirimsiz tabakaya ulaştığı yerde kaynak olarak çıkar.'),
  ('Akdeniz\'in Türkiye kıyılarında delta oluşumunu kolaylaştıran etkenlerden biri aşağıdakilerden hangisidir?', 'Gel-git genliğinin küçük olması', ['Denizin tuzluluğunun düşük olması', 'Kıyıların fiyort tipinde olması', 'Akarsuların hiç alüvyon taşımaması'], 'Gel-git etkisi zayıf denizlerde akarsuların getirdiği alüvyon ağızda birikebilir; Akdeniz\'de gel-git genliği küçüktür.'),
  ('Türkiye\'de bir akarsuyun Basra Körfezi\'ne ulaşan bir havzada yer aldığı biliniyorsa bu akarsu aşağıdakilerden hangisi olabilir?', 'Murat Nehri', ['Çoruh Nehri', 'Kura Nehri', 'Seyhan Nehri'], 'Murat, Karasu ile birleşerek Fırat\'ı oluşturur; Fırat sularını Dicle ile birleşip Şattülarap üzerinden Basra Körfezi\'ne ulaştırır.'),
  ('Aşağıdaki akarsulardan hangisi Kızılırmak\'ın bir koludur?', 'Delice Irmağı', ['Porsuk Çayı', 'Kelkit Çayı', 'Ankara Çayı'], 'Delice Irmağı Yozgat-Kırıkkale çevresinden gelerek Kızılırmak\'a katılır. Porsuk ve Ankara çayları Sakarya\'ya, Kelkit ise Yeşilırmak\'a karışır.'),
  ('Fırat üzerindeki barajlar akış yönüne göre yukarıdan aşağıya doğru sıralanırsa doğru sıra hangisidir?', 'Keban - Karakaya - Atatürk - Birecik', ['Atatürk - Keban - Birecik - Karakaya', 'Birecik - Atatürk - Karakaya - Keban', 'Karakaya - Keban - Birecik - Atatürk'], 'Fırat kuzeyden güneye akar: önce Keban (Elazığ), sonra Karakaya (Malatya-Diyarbakır), Atatürk ve en aşağıda Birecik gelir.'),
  ('Fırat ve Dicle\'nin Türkiye\'deki akarsular arasında enerji potansiyeli bakımından öne çıkmasının en önemli nedeni hangisidir?', 'Yüksek kaynak alanı ile bol su taşımaları', ['Kıyı ovalarından geçmeleri', 'Düzensiz rejimli olmaları', 'Kapalı havzaya akmaları'], 'Bu nehirler yüksek yaylalardan doğup derin vadilerden geçerek düşü yüksekliği kazanır; ayrıca bol su taşırlar.'),
  ('Dicle\'nin Türkiye-Suriye-Irak sınırının kesiştiği yere yakın bir noktada Türkiye\'den ayrıldığı ilçe hangisidir?', 'Cizre', ['Bismil', 'Hasankeyf', 'Siverek'], 'Dicle Şırnak\'ın Cizre ilçesinden geçerek kısa bir süre sınırı oluşturur ve Irak\'a girer.'),
  ('Seyhan Nehri\'ni oluşturan iki önemli kol hangisinde doğru verilmiştir?', 'Zamantı ve Göksu', ['Karasu ve Murat', 'Kelkit ve Tozanlı', 'Porsuk ve Mudurnu'], 'Kayseri\'den gelen Zamantı ile Göksu birleşerek Seyhan\'ı oluşturur; nehir Adana\'dan geçerek Akdeniz\'e dökülür.'),
  ('Bergama\'dan geçen ve Çandarlı Körfezi\'ne dökülen akarsu hangisidir?', 'Bakırçay', ['Gediz', 'Küçük Menderes', 'Gönen Çayı'], 'Bakırçay, Bergama Ovası\'ndan geçip Çandarlı Körfezi\'nde Ege\'ye ulaşır.'),
  ('Simav ve Nilüfer çaylarını alarak Marmara Denizi\'ne dökülen akarsu hangisidir?', 'Susurluk', ['Gönen Çayı', 'Biga Çayı', 'Kocadere'], 'Susurluk Çayı Güney Marmara\'nın en önemli akarsuyudur; Simav ve Nilüfer onun kollarıdır.'),
  ('Ege akarsularının ağızlarında geniş delta ovaları oluşmasına en çok katkı sağlayan özellik hangisidir?', 'Uzun graben ovalarından bol alüvyon taşımaları', ['Kaynaklarının buzullarla kaplı olması', 'Akdeniz\'e göre daha sert dalgalarla karşılaşmaları', 'Yatak eğimlerinin şelale oluşturacak kadar fazla olması'], 'Akarsular çöküntü ovaları boyunca bol malzeme getirir; Ege\'de gel-git zayıf olduğundan bu malzeme ağızda birikir.'),
  ('Aras Nehri\'nin doğduğu dağlık alan hangisidir?', 'Bingöl Dağları', ['Kaçkar Dağları', 'Allahuekber Dağları', 'Munzur Dağları'], 'Aras, Bingöl Dağları\'ndan doğup Pasinler Ovası\'ndan geçer ve Iğdır\'da sınır boyunca akar.'),
  ('Antalya\'daki Manavgat Çayı\'nın yaz kuraklığına rağmen yıl boyunca bol su taşımasının nedeni aşağıdakilerden hangisidir?', 'Toroslar\'daki karstik kaynaklardan beslenmesi', ['Buzul göllerinden beslenmesi', 'Muson yağışlarıyla beslenmesi', 'Kapalı bir havzanın çıkışında bulunması'], 'Kalker arazide yeraltında biriken sular kaynaklar hâlinde yıl boyu düzenli olarak çıkar ve akarsuyu besler.'),
  ('Isparta\'da bir volkan çukurunda oluşmuş ve şehrin içme suyu kaynakları arasında yer almış göl hangisidir?', 'Gölcük Gölü', ['Eğirdir Gölü', 'Kovada Gölü', 'Burdur Gölü'], 'Gölcük Gölü sönmüş bir volkanın krater çukurunda birikmiş sulardan oluşur.'),
  ('Büyük Menderes Nehri\'nin getirdiği alüvyonların eski bir körfezin önünü kapatmasıyla oluşan göl hangisidir?', 'Bafa Gölü', ['Köyceğiz Gölü', 'Salda Gölü', 'Işıklı Gölü'], 'Bafa Gölü bir zamanlar Latmos Körfezi\'nin parçasıydı; Büyük Menderes alüvyonlarıyla denizden ayrılmıştır.'),
  ('Ankara\'daki Mogan ve Eymir göllerinin oluşumu nasıl açıklanır?', 'Akarsu alüvyonlarının bir vadiyi kapatması', ['Volkan kraterinde su birikmesi', 'Buzulların oyduğu çanakta su birikmesi', 'Deniz kıyısında kıyı okunun koyu kapatması'], 'Bu göller bir akarsuyun ana vadiye getirdiği alüvyon setinin yan vadinin önünü kapatmasıyla oluşmuştur.'),
  ('Antalya\'nın Elmalı ilçesindeki karstik ovada yer alan göl hangisidir?', 'Avlan Gölü', ['Kovada Gölü', 'Köyceğiz Gölü', 'Sapanca Gölü'], 'Avlan Gölü Elmalı polyesinde kalkerin çözünmesiyle oluşan çukurda bulunur.'),
  ('Beyşehir ve Eğirdir göllerinin oluşumuyla ilgili en doğru ifade hangisidir?', 'Hem tektonik hem karstik süreçlerin etkisiyle oluşmaları', ['Volkanik lavlarla vadilerin kapanması', 'Akarsu alüvyonunun körfezi doldurması', 'Buzul sirklerinde suyun birikmesi'], 'Göller Yöresi\'ndeki bu göller kırılmalarla oluşan çanakların kalker çözünmesiyle genişlemesi sonucu meydana gelmiştir.'),
  ('Karstik göllerin su seviyesinin kısa sürede belirgin biçimde değişebilmesinin nedeni nedir?', 'Tabandaki düdenlerden suyun yer altına kaçabilmesi', ['Göllerin denizle bağlantılı olması', 'Göllerin lav setleriyle çevrili olması', 'Göllerin yalnız buzullardan beslenmesi'], 'Kalker tabandaki düden ve çatlaklar suyu yer altına iletir; bu nedenle karstik göllerde kuruma ve taşma görülebilir.'),
  ('Muş\'taki Haçlı Gölü ile Bitlis\'teki Nazik Gölü\'nün ortak oluşum özelliği nedir?', 'Volkanik lavların set oluşturması', ['Kıyı okuyla denizden ayrılmaları', 'Kalkerin çözünmesiyle oluşmaları', 'Heyelan malzemesiyle oluşmaları'], 'Doğu Anadolu\'daki bu göller lav akıntılarının çukurları kapatmasıyla oluşmuş volkanik set gölleridir.'),
  ('Tuz Gölü\'nün flamingolar için önemli bir üreme alanı olmasında hangi özelliği etkilidir?', 'Sığ ve tuzlu sularında bol bulunan küçük canlılar', ['Derin ve soğuk sularının olması', 'Çevresinin sık ormanlarla kaplı olması', 'Kışın tamamen donması'], 'Flamingolar sığ tuzlu sulardaki küçük kabuklular ve alglerle beslenir; gölün ıssız adacıkları yuvalamaya uygundur.'),
  ('Göksu Deltası\'nda yer alan ve önemli bir kuş yaşam alanı olan lagün hangisidir?', 'Paradeniz', ['Akyatan', 'Gala Gölü', 'Terkos Gölü'], 'Silifke\'deki Göksu Deltası\'nda bulunan Paradeniz Lagünü sulak alan olarak korunur.'),
  ('Meriç Deltası\'nda, Edirne\'nin Enez ilçesi yakınında bulunan sulak alan gölü hangisidir?', 'Gala Gölü', ['Mogan Gölü', 'Paradeniz', 'Bafa Gölü'], 'Gala Gölü Meriç Nehri\'nin deltasında yer alır ve milli park olarak korunur.'),
  ('Türkiye\'nin ilk jeotermal elektrik santrali hangi sahada kurulmuştur?', 'Denizli Kızıldere', ['Afyonkarahisar Ömer', 'Aydın Germencik', 'Yalova Termal'], 'Kızıldere jeotermal santrali 1984\'te üretime başlamış ve Türkiye\'nin ilk jeotermal elektrik santrali olmuştur.'),
  ('Kıyı ovalarında aşırı yeraltı suyu çekilmesinin olası bir sonucu aşağıdakilerden hangisidir?', 'Deniz suyunun akiferlere sızarak tuzlanma yapması', ['Yağış miktarının artması', 'Akarsuların debisinin yükselmesi', 'Kıyı ovasının deniz seviyesinin üstüne yükselmesi'], 'Taban suyu seviyesi düşünce tuzlu deniz suyu yer altında karaya doğru ilerler ve kuyular tuzlanır.'),
  ('Kuzey Anadolu Dağları\'nda orman üst sınırının güney yamaçlarda kuzey yamaçlara göre daha yüksekte bulunmasının nedeni nedir?', 'Güney yamaçların daha çok ısı alması', ['Güney yamaçların daha fazla yağış alması', 'Güney yamaçların denize daha yakın olması', 'Kuzey yamaçların daha alçak olması'], 'Bakı etkisiyle güney yamaçlar daha sıcaktır; bu nedenle ağaç yetişme sınırı ve tarım sınırı daha yukarı çıkar.'),
  ('Akdeniz kıyısında kışların ılık geçmesine en az katkı yapan etken aşağıdakilerden hangisidir?', 'Toroslar\'ın kuzeyindeki platoların genişliği', ['Güney enlemlerinde bulunma', 'Toroslar\'ın soğuk hava kütlelerini engellemesi', 'Denizin ılıtıcı etkisi'], 'Kıyının güneyde olması, dağların kuzeyden gelen soğuk havayı engellemesi ve deniz etkisi kışları ılıtır; iç platoların genişliği ise kıyı kışını ılıtmaz.'),
  ('Sıcaklıklar deniz seviyesine indirgendiğinde Türkiye\'de eş sıcaklık eğrilerinin genel olarak hangi etkene göre dağıldığı görülür?', 'Enleme', ['Boylama', 'Bitki örtüsüne', 'Toprak türüne'], 'Deniz seviyesine indirgeme yükselti etkisini ortadan kaldırır; geriye kalan temel etken enlem olur.'),
  ('Iğdır Ovası\'nın yağışının az olmasının nedeni aşağıdakilerden hangisidir?', 'Yüksek dağlarla kuşatılmış bir çukur olması', ['Karadeniz\'den gelen nemli havaya doğrudan açık olması', 'Akdeniz kıyısına yakın olması', 'Yüksek bir plato üzerinde bulunması'], 'Iğdır çevresindeki dağlar nemli hava kütlelerini engeller; çukurda alçalan hava ısınıp kurur.'),
  ('Doğu Karadeniz kıyısında yağışın en fazla olduğu mevsim hangisidir?', 'Sonbahar', ['İlkbahar', 'Yaz', 'Kış'], 'Karadeniz kıyısında her mevsim yağış görülür; ancak deniz suyunun hâlâ ılık olduğu sonbaharda yağış en yüksek düzeyine çıkar.'),
  ('Gündüz karadan denize, gece denizden karaya esen yerel rüzgâr ifadesinin yanlış olmasının nedeni nedir?', 'Gündüz kara daha çabuk ısındığı için rüzgâr denizden karaya eser.', ['Gündüz deniz daha çabuk ısındığından rüzgâr hiç esmez.', 'Meltemler yalnız kışın oluştuğundan bu ifade geçersizdir.', 'Meltemler yalnız dağ ile ova arasında görüldüğü için kıyıda esmez.'], 'Gündüz ısınan karada alçak basınç oluşur ve hava denizden karaya akar (deniz meltemi); gece bu durum tersine döner.'),
  ('Muğla\'nın Köyceğiz yöresinde yetişen ve dünyada çok sınırlı bir alanda bulunan endemik ağaç hangisidir?', 'Sığla', ['Datça hurması', 'Kasnak meşesi', 'Kazdağı göknarı'], 'Sığla (Anadolu günlüğü) ağacı Köyceğiz-Marmaris çevresindeki sulak ovalarda yetişir; reçinesi eskiden beri kullanılır.'),
  ('İç Anadolu\'daki step alanlarının bir kısmının eskiden orman olduğu, insan etkisiyle steplere dönüştüğü düşünülür. Bu steplere ne ad verilir?', 'Antropojen step', ['Alpin step', 'Tropikal step', 'Kıyı kumul stebi'], 'İnsanların ağaçları kesmesi ve aşırı otlatma sonucu ormanların yerini alan steplere antropojen (insan kaynaklı) step denir.'),
  ('Kuzey Anadolu Dağları\'nda kuzey yamaçlarla güney yamaçların bitki örtüsü karşılaştırıldığında güney yamaçlar için hangisi doğrudur?', 'Kuru ormanlar ve yer yer stepler görülür.', ['Gür nemli ormanlar daha geniş yer kaplar.', 'Ormanlar ağırlıkla kayın ve kızılağaçtan oluşur.', 'Ağaç sınırı daha alçaktadır.'], 'Güney yamaçlar yağış gölgesindedir; meşe ve sarıçamdan oluşan kuru ormanlar ve yer yer stepler yer alır. Bakı nedeniyle ağaç sınırı daha yüksektir.'),
  ('Kars ve Ardahan yöresindeki çayırlar altında oluşan, humusça zengin koyu renkli toprak hangisidir?', 'Çernozyom', ['Podzol', 'Terra rossa', 'Laterit'], 'Çayır otlarının çürümesiyle oluşan bol humus toprağa siyah renk ve yüksek verim kazandırır.'),
  ('Dağ yamaçlarından yer çekimi ve yüzey sularıyla taşınıp eteklerde biriken malzemeden oluşan topraklara ne ad verilir?', 'Kolüvyal topraklar', ['Alüvyal topraklar', 'Lös toprakları', 'Kırmızı Akdeniz toprakları'], 'Kolüvyal topraklar yamaç eteklerinde, kısa mesafeden taşınmış köşeli ve karışık malzemeden oluşur.'),
  ('Türkiye\'de Kuaterner buzullaşmasının izlerinin yalnız yüksek dağlarda görülmesinin nedeni nedir?', 'Kalıcı kar sınırının yükseklerde olması', ['Alçak alanların o dönemde deniz altında olması', 'Buzul izlerinin alçak alanlarda depremle silinmesi', 'Alçak alanlarda hiç kar yağmaması'], 'Türkiye kıta buzullarıyla örtülmemiştir; yalnız kalıcı kar sınırının üzerine çıkan dağlarda buzullar gelişmiştir.'),
  ('Killi bir tabakanın üzerindeki toprak kütlesinin yağıştan sonra yamaç aşağı kaymasında kil tabakasının rolü nedir?', 'Islanınca kaygan bir yüzey oluşturması', ['Suyu çatlaklarından hızla derinlere geçirmesi', 'Toprağı daha da sağlamlaştırması', 'Yamacın eğimini azaltması'], 'Kil su geçirmez ve ıslanınca kayganlaşır; üstteki suya doymuş ağır kütle bu yüzey üzerinde kayar.'),
  ('İzmit Körfezi\'nin güneyinde, Yalova ile Bursa arasında uzanan dağ sırası hangisidir?', 'Samanlı Dağları', ['Köroğlu Dağları', 'Istranca Dağları', 'Bozdağlar'], 'Samanlı Dağları Armutlu Yarımadası ile Kocaeli arasında doğu-batı yönünde uzanır.'),
  ('Gediz Nehri\'nin kaynağını aldığı, Uşak-Kütahya sınırında yer alan dağ hangisidir?', 'Murat Dağı', ['Bozdağlar', 'Spil Dağı', 'Aydın Dağları'], 'Gediz Murat Dağı\'ndan doğar ve batıya doğru akarak Ege\'ye dökülür.'),
  ('Bayburt ile Erzurum arasında yer alan yüksek geçit hangisidir?', 'Kop Geçidi', ['Zigana Geçidi', 'Sertavul Geçidi', 'Çubuk Beli'], 'Kop Geçidi Kop Dağı üzerinde, Bayburt-Erzurum yolunda bulunur ve kışın zor geçilen yüksek bir geçittir.'),
  ('Antalya ile Burdur arasında Toroslar\'ı aşan ve Akdeniz kıyısını Göller Yöresi\'ne bağlayan geçit hangisidir?', 'Çubuk Beli', ['Gülek Boğazı', 'Kop Geçidi', 'Zigana Geçidi'], 'Çubuk Beli Batı Toroslar\'da Antalya\'yı Burdur ve Isparta\'ya bağlayan yolun üzerindedir.'),
  ('Marmara\'nın kuzeyinde Karadeniz kıyısındaki Terkos (Durusu) Gölü\'nün oluşum türü nedir?', 'Kıyı set gölü', ['Krater gölü', 'Karstik göl', 'Buzul sirki gölü'], 'Terkos, Karadeniz kıyısında kıyı kumullarının bir koyu kapatmasıyla oluşmuş bir lagündür.'),
  ('Muğla\'daki Gökova Körfezi\'nin doğu-batı doğrultusunda uzun ve dar bir biçime sahip olmasının kökeni nedir?', 'Fayların sınırladığı bir çöküntü olması', ['Bir akarsu deltasının kıyıyı ilerletmesi', 'Bir buzul vadisinin deniz altında kalması', 'Bir volkan kalderasının denizle dolması'], 'Gökova Körfezi Ege\'deki graben sisteminin denizle dolmuş bir parçasıdır; kuzey ve güney kenarları faylarla sınırlanır.'),
  ('Akdeniz Bölgesi\'nde Adana Bölümü ile Antalya Bölümü arasında doğal sınır görevi gören yer şekli hangisidir?', 'Orta Toroslar\'ın Taşeli kesimi', ['Gediz grabeni ve Bozdağlar kütlesi', 'Ergene Havzası', 'Kızılırmak vadisi'], 'Taşeli Platosu ile Orta Toroslar, Akdeniz Bölgesi\'nin batı ve doğu bölümlerini birbirinden ayıran yüksek kütledir.'),
  ('Antalya Ovası\'nın büyük bölümünü oluşturan ve kalkerli suların çökelmesiyle oluşan kayaç hangisidir?', 'Traverten', ['Granit', 'Bazalt', 'Kuvarslı kumtaşı'], 'Antalya\'nın üzerinde kurulduğu düzlük, karstik kaynak sularının çökelttiği kalın traverten katmanlarından oluşur.'),
  ('İç Anadolu\'da yer alan ve Sakarya ile Kızılırmak havzaları arasında uzanan dağlık-platolu alan için en uygun yorum hangisidir?', 'Su bölümü çizgisi oluşturur.', ['Kapalı bir göl havzasıdır.', 'İki havzayı birleştiren bir volkanik krater alanıdır.', 'Delta ovasıdır.'], 'Bu yüksek alanlar yağış sularını iki büyük havzaya ayırır; bu nedenle su bölümü işlevi görür.'),
  ('Konya Ovası çevresinde görülen eski kıyı çizgileri ve göl taraçaları neyin kanıtıdır?', 'Eski bir göl varlığının', ['Ovanın yakın zamanda denizden yükseldiğinin', 'Ovanın volkanik lavlarla örtüldüğünün', 'Ovada buzulların bugün de var olduğunun'], 'Kuaterner\'de daha yağışlı dönemlerde Konya çanağında geniş bir göl bulunuyordu; çekilirken kıyı izleri bıraktı.'),
  ('Tokat\'ta Yeşilırmak\'ın suladığı ve Karadeniz Bölgesi\'nin iç kesiminde yer alan ova hangisidir?', 'Kazova', ['Uluova', 'Suruç Ovası', 'Altınova'], 'Kazova Tokat\'ın batısında Yeşilırmak vadisi boyunca uzanan verimli bir ovadır.'),
  ('Elazığ\'da yer alan ve Uluova olarak bilinen ova hangi akarsu havzasındadır?', 'Fırat', ['Aras', 'Kura', 'Seyhan'], 'Uluova Elazığ\'ın doğusunda Keban Barajı gölüne yakın bir tektonik ovadır; Fırat havzasında yer alır.'),
  ('Doğu Anadolu\'da ovaların genellikle yüksek dağlar arasında çanaklar hâlinde bulunmasının sonucu aşağıdakilerden hangisidir?', 'Kışın soğuk havanın çanakta birikmesi', ['Ovaların deniz etkisine açık olması', 'Ovalarda kar yağışının hiç görülmemesi', 'Ovaların büyük delta düzlükleri olması'], 'Ağır soğuk hava kışın çukurlara çöker; bu nedenle Doğu Anadolu ovalarında sıcaklık terselmesi ve çok düşük sıcaklıklar görülür.'),
  ('Güneydoğu Anadolu\'nun Dicle Bölümü ile Orta Fırat Bölümü arasında doğal sınır oluşturan volkanik kütle hangisidir?', 'Karacadağ', ['Nemrut Dağı', 'Ağrı Dağı', 'Erciyes Dağı'], 'Karacadağ, Fırat ve Dicle havzaları arasında su bölümü görevi yaparak bölgeyi iki bölüme ayırır.'),
  ('Karadeniz\'in belli bir derinlikten sonra oksijensiz olması ve bu nedenle canlı yaşamının sınırlı kalmasının sonucu nedir?', 'Derin sularda hidrojen sülfür birikmesi', ['Yüzey sularının donması', 'Yüzeyde mercan resiflerinin oluşması', 'Kıyılarda büyük gel-git olaylarının görülmesi'], 'Az tuzlu üst katman ile tuzlu alt katman karışmadığından derinlere oksijen ulaşmaz; bu ortamda hidrojen sülfür birikir.'),
  ('Tarsus şehrinin içinden geçen ve şehirde şelale oluşturan akarsu hangisidir?', 'Berdan Çayı', ['Seyhan Nehri', 'Ceyhan Nehri', 'Göksu Nehri'], 'Berdan Çayı Toroslar\'dan inerek Tarsus\'tan geçer ve şehir merkezinde Tarsus Şelalesi\'ni oluşturur.'),
  ('Seyhan ve Ceyhan\'ın Akdeniz akarsuları arasında uzun olmasının nedeni nedir?', 'Kaynaklarının Toroslar\'ın gerisinde olması', ['Çukurova\'nın deniz seviyesinin altında olması', 'Karstik kaynaklarla beslenmeleri', 'Akdeniz\'in gel-git etkisinin güçlü olması'], 'Bu akarsular İç Anadolu\'nun güneydoğusundan ve Uzunyayla\'dan doğar, Toroslar\'ı derin vadilerle yararak Çukurova\'ya ulaşır.'),
  ('Isparta\'daki Eğirdir Gölü\'nün suyunun tatlı olmasının nedeni nedir?', 'Gölün bir çıkışının bulunması', ['Gölün denizle bağlantılı olması', 'Göle hiç akarsu ulaşmaması', 'Gölün buzullarla beslenmesi'], 'Eğirdir\'in fazla suyu güneydeki Kovada Gölü\'ne akar; gölün bir çıkışı bulunduğundan tuzlar birikmez.'),
  ('Göller Yöresi\'ndeki göllerden Burdur Gölü tuzlu, Beyşehir Gölü tatlıdır. Bu farkın temel nedeni nedir?', 'Beyşehir\'in bir gideğeninin bulunması', ['Burdur Gölü\'nün daha fazla yağış alması', 'Beyşehir Gölü\'nün volkanik olması', 'Burdur Gölü\'nün deniz kıyısında olması'], 'Beyşehir Gölü\'nün suları Beyşehir Kanalı (Çarşamba Çayı) ile Konya Ovası\'na akar; Burdur\'un ise çıkışı yoktur.'),
  ('Kırşehir\'de bulunan ve kuşların konaklama alanı olarak korunan kapalı havza gölü hangisidir?', 'Seyfe Gölü', ['Hazar Gölü', 'Mogan Gölü', 'Kuyucuk Gölü'], 'Seyfe Gölü sığ ve tuzlu bir kapalı havza gölüdür; flamingolar ve göçmen kuşlar için önem taşır.'),
  ('Van\'ın doğusunda yer alan ve sularının Van Gölü gibi sodalı olduğu bilinen göl hangisidir?', 'Erçek Gölü', ['Hazar Gölü', 'Nazik Gölü', 'Çıldır Gölü'], 'Erçek Gölü kapalı bir çanakta yer alır; buharlaşma nedeniyle suları sodalıdır.'),
  ('Ağrı\'da yer alan ve Türkiye\'nin en yüksekte bulunan büyük göllerinden olan lav set gölü hangisidir?', 'Balık Gölü', ['Hazar Gölü', 'Tortum Gölü', 'Van Gölü'], 'Balık Gölü yaklaşık 2.200 metre yükseltide, lavların bir vadiyi kapatmasıyla oluşmuştur.'),
  ('Göller Yöresi\'ndeki göllerin bir kısmının Akdeniz\'e yer altından boşaldığı düşünülür. Bu durumun temel nedeni nedir?', 'Kalkerli zeminin geçirimliliği', ['Göllerin deniz seviyesinin altında olması', 'Göllerin volkan kraterinde bulunması', 'Bölgede buzulların erimesi'], 'Kalker çatlaklarından ve düdenlerden sızan sular yer altı kanallarıyla Toroslar\'ın güney eteklerindeki kaynaklara ulaşır.'),
  ('Yaz aylarında Ege ve Akdeniz kıyılarında yağışın çok az olmasında Asor yüksek basıncının rolü nedir?', 'Alçalan havanın bulut oluşumunu önlemesi', ['Bölgeye bol nemli hava taşıması', 'Bölgede kar yağışlarını artırması', 'Sıcaklığın sıfırın altına düşmesine yol açması'], 'Yüksek basınç alanlarında hava alçalarak ısınır ve kurur; yükselici hareket olmadığından yağış oluşmaz.'),
  ('Kışın sakin ve açık gecelerde Erzurum Ovası\'nda çevredeki yamaçlara göre daha düşük sıcaklıklar ölçülmesinin nedeni nedir?', 'Soğuk havanın tabanda birikmesi', ['Ovanın yamaçlardan daha yüksek olması', 'Ovada bitki örtüsünün sık olması', 'Ovaya denizden sıcak hava gelmesi'], 'Soğuyan yoğun hava yamaçlardan aşağı süzülerek çanakta birikir; yükseldikçe sıcaklığın arttığı bu duruma sıcaklık terselmesi denir.'),
  ('Sıcaklık terselmesinin görüldüğü bir kış gününde bir şehrin üzerinde hava kirliliğinin artmasının nedeni nedir?', 'Dikey hava hareketlerinin durması', ['Rüzgâr hızının çok artıp kirleticileri taşıması', 'Yağışın sürekli düşmesi', 'Sıcak havanın yerde birikmesi'], 'Sıcak bir katmanın altında kalan soğuk hava yükselemez; bacalardan çıkan kirleticiler dağılamadan yere yakın birikir.'),
  ('Ankara\'nın Kızılcahamam ile Polatlı arasında bitki örtüsünde kuzeyden güneye ormandan steplere geçiş görülmesinin temel iklim nedeni hangisidir?', 'Güneye doğru yağışın azalması', ['Güneye doğru yükseltinin artması', 'Kuzeye doğru sıcaklığın artması', 'Güneye doğru deniz etkisinin artması'], 'Kuzeydeki dağlık alanlar daha fazla yağış alır ve orman taşır; güneydeki yağış gölgesindeki düzlüklerde step egemendir.'),
  ('Türkiye\'de kış aylarında iç kesimlerde açık ve ayazlı günlerin, kıyılarda ise yağışlı günlerin fazla olması neyi gösterir?', 'İç kesimde yüksek basıncın egemen olduğunu', ['İç kesimlerin denizden nem almasını', 'Kıyıların kuraklık yaşamasını', 'Kıyıların iç kesimlerden daha karasal bir iklim taşıdığını'], 'Kışın soğuyan iç kesimlerde yüksek basınç oluşur ve hava durgun-açık olur; kıyılar ise alçak basınç ve cephelerin yolu üzerindedir.'),
  ('Bir delta oluşabilmesi için aşağıdakilerden hangisinin gerçekleşmesi gerekmez?', 'Kıyının girintili olması', ['Akarsuyun bol alüvyon taşıması', 'Kıyıda gel-git etkisinin zayıf olması', 'Akıntıların malzemeyi uzaklaştıramaması'], 'Delta için alüvyon bolluğu ile malzemenin ağızda kalması gerekir; kıyının girintili olması zorunlu değildir.'),
  ('İstanbul Boğazı\'ndaki iki katlı akıntı sisteminin Marmara Denizi\'nin canlı yaşamı açısından önemi nedir?', 'İki farklı su kütlesini buluşturması', ['Marmara\'nın tuzluluğunu Akdeniz\'in üzerine çıkarması', 'Marmara\'yı her yıl dondurması', 'Marmara\'yı tümüyle tatlı suya dönüştürmesi'], 'Az tuzlu Karadeniz suyu üstte, tuzlu Akdeniz kökenli su altta bulunur; bu tabakalaşma Marmara\'nın ekosistemini biçimlendirir.'),
  ('İzmir Körfezi\'nde bulunan ve körfezdeki en büyük ada olan ada hangisidir?', 'Uzunada', ['Cunda Adası', 'Gökçeada', 'Avşa Adası'], 'Uzunada İzmir Körfezi\'nin ağzına yakın bir konumda bulunur ve körfezdeki en büyük adadır.'),
  ('Karadeniz kıyısındaki Sinop Yarımadası\'nın Karadeniz kıyıları arasında doğal liman bakımından öne çıkmasının nedeni nedir?', 'Korunaklı bir koy oluşturması', ['Kıyının fiyort tipinde olması', 'Karadeniz\'de gel-git genliğinin büyük olması', 'Limanın göl kıyısında bulunması'], 'Sinop\'un tombolo ile karaya bağlanmış yarımadası güneyinde korunaklı bir koy oluşturur; düz Karadeniz kıyısında bu nadirdir.'),
  ('Kıyı oklarının Türkiye\'de en çok Karadeniz ve Akdeniz kıyılarındaki akarsu ağızlarında görülmesinin nedeni nedir?', 'Akarsuların kıyıya bol malzeme getirmesi', ['Bu kıyıların derin fiyortlarla kaplı olması', 'Bu denizlerde akıntının hiç olmaması', 'Kıyıların volkanik olması'], 'Kıyı akıntıları akarsuların getirdiği kum ve çakılı kıyı boyunca taşıyıp biriktirir; böylece kıyı okları ve lagünler gelişir.'),
  ('Antalya\'nın Kaş ilçesi açıklarındaki Kekova çevresinde görülen batık kalıntıları neyi gösterir?', 'Kıyının zamanla çöktüğünü', ['Bölgenin hızla yükseldiğini', 'Deniz seviyesinin yüz metre düştüğünü', 'Bölgenin buzullarla örtüldüğünü'], 'Antik yapı kalıntılarının deniz altında kalması, yer kabuğu hareketleriyle kıyının alçaldığını gösterir.'),
  ('Menderes Masifi\'nin Ege Bölgesi için jeolojik anlamı nedir?', 'Bölgenin eski ve başkalaşmış çekirdek kütlesi olması', ['Bölgedeki genç volkan konilerinin toplandığı alan olması', 'Ege\'de Kuaterner\'de oluşmuş bir delta olması', 'Bölgenin en büyük karstik polyesi olması'], 'Menderes Masifi Paleozoik ve daha eski metamorfik kayaçlardan oluşur; Ege\'nin horst-graben yapısı bu masif üzerinde gelişmiştir.'),
  ('Kuzey Anadolu Fayı boyunca blokların birbirine göre hareketi nasıldır?', 'Yatay doğrultuda yana kayma', ['Yalnız dikey düşey hareket', 'Blokların üst üste bindirmesi', 'Blokların hiç hareket etmemesi'], 'KAF sağ yanal doğrultu atımlı bir faydır; kuzey ve güney bloklar birbirine göre yatayda kayar.'),
  ('Ege Bölgesi\'ndeki fayların gerilme sonucu oluşmasının yer şekillerine etkisi nedir?', 'Horst ve grabenlerin oluşması', ['Tabakaların kıvrılıp sıradağlara dönüşmesi', 'Volkan konilerinin sıralanması', 'Karstik çukurların yayılması'], 'Yer kabuğunun kuzey-güney yönünde gerilmesi normal faylara yol açar; aralarında grabenler çöker, horstlar yükselir.'),
  ('Marmara Denizi\'nin çukurluklarının Kuzey Anadolu Fayı ile ilişkisi aşağıdakilerden hangisinde doğru verilmiştir?', 'Fay kolları boyunca çukurlar oluşmuştur.', ['Marmara bir volkan kalderasıdır.', 'Marmara buzulların oyduğu bir çanaktır.', 'Marmara, kalkerin çözünmesiyle oluşmuş bir polyedir.'], 'KAF Marmara\'da kollara ayrılır; bu kollar boyunca derin çukurlar (Tekirdağ, Orta ve Çınarcık çukurları) oluşmuştur.'),
  ('Ağrı Dağı ve Erciyes Dağı\'nın biçim bakımından ortak özelliği nedir?', 'Tabakalı (strato) volkan olmaları', ['Yayvan kalkan volkanlar olmaları', 'Patlama çukurlarından oluşmaları', 'Kalderalarında büyük göller bulunması'], 'Her ikisi de lav ve piroklastik malzemenin ardalanmasıyla yükselmiş dik yamaçlı stratovolkanlardır.'),
  ('Karapınar\'daki Meke Gölü\'nün bulunduğu çukurun oluşumu nasıl açıklanır?', 'Patlamayla açılan maar', ['Buzulun oyduğu sirk', 'Kalkerin çözündüğü obruk', 'Fayla çöken graben'], 'Magma yeraltı suyuyla karşılaşınca şiddetli buhar patlaması olur ve geniş, sığ bir çukur (maar) oluşur.'),
  ('Ankara\'da eski yapılarda kullanılan ve Ankara taşı olarak bilinen volkanik kayaç hangisidir?', 'Andezit', ['Mermer', 'Granit', 'Traverten'], 'Ankara taşı pembe-gri renkli bir andezittir; Ankara çevresindeki eski volkanik kütlelerden elde edilmiştir.'),
  ('Doğu Anadolu Fayı\'nın güneybatı ucunda bağlandığı yapı aşağıdakilerden hangisidir?', 'Ölü Deniz Fay Zonu', ['Ege graben sistemi', 'Kuzey Anadolu Fayı\'nın batı kolu', 'Kafkas bindirme kuşağı'], 'DAF Hatay çevresinde güneye uzanan Ölü Deniz Fayı ile birleşir; bu fay Arap levhası ile Afrika levhası arasındaki sınırı oluşturur.'),
  ('Akarsuyun bir menderesin boynunu keserek eski kıvrımı terk etmesiyle oluşan göl türüne ne ad verilir?', 'Kopuk menderes gölü', ['Volkanik krater gölü', 'Lagün', 'Sirk gölü'], 'Taşkınlarda akarsu kıvrımın dar boynunu aşarak kısa yoldan akar; terk edilen kıvrım at nalı biçimli bir göl olarak kalır.'),
  ('Bir akarsu üzerine baraj yapıldığında barajın gerisindeki kesimde akarsuyun aşındırma ve biriktirme davranışı nasıl değişir?', 'Göl gerisinde biriktirme artar.', ['Taban seviyesi düşer ve akarsu derine aşındırır.', 'Akarsu tümüyle aşındırma yapmaya başlar.', 'Akarsu biriktirme yapamaz hâle gelir.'], 'Baraj gölü yeni bir yerel taban seviyesidir; göle giren akarsu yavaşlar ve taşıdığı malzemeyi biriktirir.'),
  ('Kastamonu\'da Devrekani Çayı\'nın kalker kütleleri yarmasıyla oluşan derin vadi hangisidir?', 'Valla Kanyonu', ['Ihlara Vadisi', 'Köprülü Kanyon', 'Saklıkent Kanyonu'], 'Valla Kanyonu Küre Dağları Milli Parkı içinde, yüzlerce metre derinliğe ulaşan dik yamaçlı bir kanyondur.'),
  ('Sivas ile Kayseri arasında yer alan ve yüksek düzlük yapısıyla bilinen plato hangisidir?', 'Uzunyayla Platosu', ['Haymana Platosu', 'Cihanbeyli Platosu', 'Teke Platosu'], 'Uzunyayla Platosu Sivas\'ın güneybatısı ile Kayseri\'nin kuzeydoğusunda yüksek ve çayırlık bir düzlüktür; Zamantı Irmağı\'nın kaynak alanı buradadır.'),
  ('Konya\'nın kuzeyinde Tuz Gölü\'nün batısında uzanan plato hangisidir?', 'Cihanbeyli Platosu', ['Obruk Platosu', 'Taşeli Platosu', 'Haymana-Polatlı Platosu'], 'Cihanbeyli Platosu Tuz Gölü havzasının batısındaki yarı kurak düzlüktür.'),
  ('Gaziantep ve Şanlıurfa platolarının akarsular tarafından derince yarılmamış olmasının nedeni aşağıdakilerden hangisidir?', 'Yağışın az olması', ['Kalker yapının hiç bulunmaması', 'Platoların deniz seviyesinde bulunması', 'Akarsuların bölgede taşkın yapmaması nedeniyle eğimin artması'], 'Kurak iklimde yüzey akışı zayıftır; akarsular az olduğu için platolar geniş ve az yarılmış kalır.'),
  ('Elmalı gibi karstik ovalarda kışın ve ilkbaharda geçici göller oluşabilmesinin nedeni nedir?', 'Düdenlerin gelen suyu yetiştirememesi', ['Ovaya deniz suyunun girmesi', 'Volkanik kaynakların ovaya bol sıcak su vermesi', 'Buzulların ova tabanında erimesi'], 'Bol yağışlı dönemde polyeye dolan suyu düdenler hızla boşaltamaz; ova kısmen göl hâline gelir.'),
  ('Kıyıya paralel uzanan dağların gerisinde yağışın birden azalmasının Türkiye\'deki en iyi örneği hangi iki yer arasında görülür?', 'Rize ile Bayburt arası', ['İzmir ile Manisa arası', 'Edirne ile Kırklareli arası', 'Adana ile Mersin arası'], 'Rize-Trabzon kıyısında yağış 2.000 mm\'yi aşarken dağların gerisindeki Bayburt-Gümüşhane yöresi yağış gölgesinde kalır.'),
  ('Bir akarsu kaynağından ağzına kadar sırasıyla dar boğazlar, geniş bir çöküntü ovası ve denize ulaştığı yerde bir delta oluşturuyor. Bu akarsu için hangisi söylenebilir?', 'Ağzında gel-git etkisi zayıftır.', ['Kapalı havzada son bulur.', 'Yatağı tümüyle kalker içinde yer alır.', 'Akarsu buzullarla beslenir ve hiç alüvyon taşımaz.'], 'Delta oluşumu akarsuyun getirdiği alüvyonun ağızda kalmasını gerektirir; bu ancak gel-git ve akıntıların zayıf olduğu kıyılarda olur.'),
  ('Bir akarsuyun kollarından birinin kar erimesiyle, diğerinin karstik kaynaklarla beslendiği biliniyor. Bu akarsuyun ana kolunda yaz akımı ile ilgili en doğru yorum hangisidir?', 'Karstik kaynaklar yaz akımını destekler.', ['Akarsu yazın tamamen kurur.', 'Yazın akım her zaman en yüksek düzeydedir.', 'Kar erimesi yazın akımı sürekli artırır.'], 'Kar erimesi ilkbaharda biter; yaz boyunca akımı karstik kaynakların düzenli suyu sürdürür.'),
  ('Bir ovada yazın yeraltı suyu seviyesinin hızla düştüğü ve obruk oluşumlarının arttığı gözleniyor. Bu durum için en uygun açıklama hangisidir?', 'Yeraltı suyunun aşırı çekilmesi', ['Yağışın aşırı artması', 'Volkanik etkinliğin yeniden başlaması', 'Deniz seviyesinin yükselmesi'], 'Kalkerli zeminde yeraltı suyu azaldıkça boşlukların tavanı desteğini yitirir ve çöker; Konya Ovası\'nda bu durum gözlenmiştir.'),
  ('İzmir\'de güneşin Van\'dan yaklaşık bir saat sonra doğmasına karşın iki kentte de yıl boyunca öğle gölgesinin kuzeye düşmesi hangi iki konum özelliğinin birlikte sonucudur?', 'Farklı boylamda ve dönencenin kuzeyinde olmaları', ['Aynı boylamda olmaları ve Ekvator\'a yakın bulunmaları', 'Farklı enlemlerde olmaları ve aynı yükseltide bulunmaları', 'Aynı enlemde olmaları ve güney yarım kürede bulunmaları'], 'Doğuş zamanı farkı boylam farkından, gölgenin kuzeye düşmesi ise Yengeç Dönencesi\'nin kuzeyinde olmaktan kaynaklanır.'),
  ('Fethiye ile Kaş arasında akan ve antik Ksanthos kentinin yakınından geçen akarsu hangisidir?', 'Eşen Çayı', ['Dalaman Çayı', 'Aksu Çayı', 'Manavgat Çayı'], 'Eşen Çayı Batı Toroslar\'dan doğar, Ksanthos Vadisi\'nden geçip Patara yakınında Akdeniz\'e dökülür.'),
  ('Türkiye\'de doğal göllerin özellikle İç Anadolu, Göller Yöresi ve Doğu Anadolu\'da yoğunlaşmasının ortak nedeni nedir?', 'Çanak oluşturan süreçlerin yaygınlığı', ['Bu alanların bol yağış alması', 'Bu alanların deniz kıyısında yer alması', 'Bu alanlarda buzulların bugün de geniş olması'], 'Tektonik çöküntüler, karstik çanaklar ve volkanik setler bu alanlarda suyun birikmesine uygun çukurlar oluşturmuştur.'),
  ('Ankara\'nın güneyindeki Mogan Gölü\'nün fazla suyunu aldığı göl hangisidir?', 'Eymir Gölü', ['Tuz Gölü', 'Hirfanlı Barajı', 'Sapanca Gölü'], 'Mogan ve Eymir gölleri birbirine bağlıdır; Mogan\'ın fazla suyu Eymir\'e akar.'),
  ('Bir bölgede yıllık yağışın 1.000 mm\'nin üzerinde olmasına rağmen yaz aylarında bitkilerin su sıkıntısı çekmesi hangi iklim özelliğiyle açıklanır?', 'Yağışın kış aylarına yoğunlaşması', ['Yağışın her aya eşit dağılması', 'Yazların serin, bulutlu ve nemli geçmesi', 'Kışların kurak geçmesi'], 'Akdeniz kıyısındaki bazı istasyonlar bol yağış alsa da bu yağış kışın düşer; yazın kuraklık yaşanır.'),
  ('Kızılçam ormanlarının yangınlardan sonra kendini hızla yenileyebilmesinin nedeni nedir?', 'Kozalaklarının ısıyla açılması', ['Hiç yanmayan kalın bir kabuğa sahip olması', 'Yalnız nemli bölgelerde yetişmesi', 'Köklerinin yüzeyde bulunmaması'], 'Kızılçam kozalakları yangın sıcağıyla açılır; dökülen tohumlar yanmış alanda hızla filizlenir.'),
  ('Karadeniz ormanlarının altında görülen ve orman gülü, şimşir gibi bitkilerden oluşan çalı katına ne ad verilir?', 'Orman altı bitki örtüsü', ['Garig', 'Alpin çayır kuşağı', 'Akdeniz tipi maki kuşağı'], 'Nemli Karadeniz ormanlarında ağaçların altında yoğun bir çalı katı gelişir; orman gülü bunun tipik üyesidir.'),
  ('Bir istasyonda yağışın en çok ilkbahar sonu ile yaz başında düştüğü ve kışların çok soğuk geçtiği biliniyorsa bu istasyon hangi yörede olabilir?', 'Erzurum-Kars yöresi', ['Antalya kıyısı', 'İzmir kıyısı', 'Çukurova (Adana) düzlüğü'], 'Doğu Anadolu\'nun kuzeydoğusunda yağış ilkbahar sonu ve yaz başında artar; kışlar ise çok serttir.'),
  ('Kuzey Anadolu Dağları\'nın denize bakan yamaçlarındaki ormanlar ile Toroslar\'ın denize bakan yamaçlarındaki ormanlar karşılaştırıldığında hangisi doğrudur?', 'Karadeniz yamaçlarındaki ormanlar daha nemcildir.', ['Toroslar\'ın kıyı yamaçlarında kayın ve ladin baskındır.', 'İki kesimde de yalnız maki bulunur.', 'Karadeniz yamaçlarında kızılçam ve maki baskındır.'], 'Her mevsim yağış alan Karadeniz yamaçlarında nemcil geniş yapraklı ve iğne yapraklı ormanlar; Toroslar\'ın güney yamaçlarında ise kurakçıl kızılçam ve maki görülür.'),
];
